import java.util.*; public class Q14_BankingATMSimulation{static class Account{private double balance;void deposit(double x){balance+=x;System.out.println("Deposited: "+x);}void withdraw(double x){if(x<=balance){balance-=x;System.out.println("Withdrawn: "+x);}else System.out.println("Insufficient balance");}double getBalance(){return balance;}}public static void main(String[]x){Scanner s=new Scanner(System.in);Account a=new Account();int n=Integer.parseInt(s.nextLine());while(n-->0){String[]p=s.nextLine().split("\\s+");if(p[0].equalsIgnoreCase("deposit"))a.deposit(Double.parseDouble(p[1]));else if(p[0].equalsIgnoreCase("withdraw"))a.withdraw(Double.parseDouble(p[1]));else if(p[0].equalsIgnoreCase("getBalance"))System.out.println("Balance: "+a.getBalance());}}}
